MERGE [Org].DepEmpRole T
USING (SELECT * FROM @DepEmpRoleStaging) S
    ON T.RoleID = S.RoleID
    AND T.DepartmentID = S.DepartmentID
    AND T.EmployeeID = S.EmployeeID
WHEN NOT MATCHED THEN
    INSERT(RoleID, DepartmentID, EmployeeID)
    VALUES(S.RoleID, S.DepartmentID, S.EmployeeID);
